const order = $json;

return {
  json: {
    order_id: String(order.order_id),
    date: new Date(order.order_date),
    customer_id: String(order.customer_id),
    customer: order.customer_name.trim(),
    product_id: String(order.product_id),
    product: order.product_name.trim(),
    category: order.category.trim(),
    quantity: Number(order.quantity),
    price: Number(order.unit_price),
    discount: Number(order.discount || 0),
    cost: Number(order.cost_price),
    status: order.status.toLowerCase()
  }
};

// Calculate Total Revenue, Gross Revenue, Net Revenue, Discount
let grossRevenue = 0;
let totalDiscount = 0;
let netRevenue = 0;

for (const item of items) {
  const o = item.json;

  const gross = o.quantity * o.price;
  grossRevenue += gross;
  totalDiscount += o.discount;
  netRevenue += gross - o.discount;
}

return [
  {
    json: {
      gross_revenue: grossRevenue,
      discount: totalDiscount,
      net_revenue: netRevenue
    }
  }
];

// Calculate Orders, Units, Completed, Cancelled, Returned
let orders = items.length;
let units = 0;
let completed = 0;
let cancelled = 0;
let returned = 0;

for (const item of items) {
  const o = item.json;

  units += o.quantity;
  if (o.status === "completed") completed++;
  if (o.status === "cancelled") cancelled++;
  if (o.status === "returned") returned++;
}

return [
  {
    json: {
      total_orders: orders,
      units_sold: units,
      completed_orders: completed,
      cancelled_orders: cancelled,
      returned_orders: returned
    }
  }
];

// Calculate Gross Profit, Average Order Value, Margin
let revenue = 0;
let cost = 0;
let orders = items.length;

for (const item of items) {
  const o = item.json;

  revenue += (o.quantity * o.price) - o.discount;
  cost += o.quantity * o.cost;
}

const profit = revenue - cost;
const margin = revenue === 0 ? 0 : (profit / revenue) * 100;
const aov = orders === 0 ? 0 : revenue / orders;

return [
  {
    json: {
      gross_profit: profit,
      gross_margin: margin,
      average_order_value: aov
    }
  }
];

// Generate product performance metrics: Revenue, Units Sold, Orders, Profit
const products = {};

for (const item of items) {
  const o = item.json;

  const revenue = (o.quantity * o.price) - o.discount;
  const cost = o.quantity * o.cost;
  const profit = revenue - cost;

  if (!products[o.product]) {
    products[o.product] = {
      product: o.product,
      category: o.category,
      revenue: 0,
      profit: 0,
      units: 0,
      orders: new Set()
    };
  }

  products[o.product].revenue += revenue;
  products[o.product].profit += profit;
  products[o.product].units += o.quantity;
  products[o.product].orders.add(o.order_id);
}

const output = Object.values(products)
  .map(product => ({
    ...product,
    orders: product.orders.size
  }))
  .sort((a, b) => b.revenue - a.revenue);

return [
  {
    json: {
      top_products: output.slice(0, 5),
      bottom_products: output.slice(-5)
    }
  }
];

// Group by Category and calculate Revenue, Profit, Units
const categories = {};

for (const item of items) {
  const o = item.json;

  const revenue = (o.quantity * o.price) - o.discount;
  const profit = revenue - (o.quantity * o.cost);

  if (!categories[o.category]) {
    categories[o.category] = {
      category: o.category,
      revenue: 0,
      profit: 0,
      units: 0
    };
  }

  categories[o.category].revenue += revenue;
  categories[o.category].profit += profit;
  categories[o.category].units += o.quantity;
}

const output = Object.values(categories)
  .sort((a, b) => b.revenue - a.revenue);

return [
  {
    json: {
      category_performance: output
    }
  }
];

// Find Top Customers, Revenue per Customer, Orders, Average Order Value
const customers = {};

for (const item of items) {
  const o = item.json;

  const revenue = (o.quantity * o.price) - o.discount;

  if (!customers[o.customer_id]) {
    customers[o.customer_id] = {
      customer_id: o.customer_id,
      customer: o.customer,
      revenue: 0,
      orders: new Set()
    };
  }

  customers[o.customer_id].revenue += revenue;
  customers[o.customer_id].orders.add(o.order_id);
}

const output = Object.values(customers)
  .map(customer => {
    customer.orders = customer.orders.size;
    customer.average_order_value = customer.orders === 0
      ? 0
      : customer.revenue / customer.orders;
    return customer;
  })
  .sort((a, b) => b.revenue - a.revenue);

return [
  {
    json: {
      top_customers: output.slice(0, 10)
    }
  }
];

