// Prepare executive summary section from AI output
return [
  {
    json: {
      executive_summary: items[0].json.message.content
    }
  }
];

// Assemble the final HTML sales report using KPI + Analytics + AI results
const ai = items[0].json; // { chat, summary }
const analytics = $('Build Analytics JSON').first().json;

const kpi = {
  gross_revenue: analytics.gross_revenue,
  net_revenue: analytics.net_revenue,
  gross_profit: analytics.gross_profit,
  gross_margin: analytics.gross_margin,
  average_order_value: analytics.average_order_value,
  total_orders: analytics.total_orders,
  units_sold: analytics.units_sold,
  completed_orders: analytics.completed_orders,
  cancelled_orders: analytics.cancelled_orders,
  returned_orders: analytics.returned_orders
};

const topProducts = analytics.top_products || [];
const categoryPerformance = analytics.category_performance || [];
const topCustomers = analytics.top_customers || [];

function renderProductRows(rows) {
  return rows.map(p => `
    <tr>
      <td>${p.product}</td>
      <td>${p.category}</td>
      <td>${p.revenue}</td>
      <td>${p.profit}</td>
      <td>${p.units}</td>
      <td>${p.orders}</td>
    </tr>
  `).join('');
}

function renderCategoryRows(rows) {
  return rows.map(c => `
    <tr>
      <td>${c.category}</td>
      <td>${c.revenue}</td>
      <td>${c.profit}</td>
      <td>${c.units}</td>
    </tr>
  `).join('');
}

function renderCustomerRows(rows) {
  return rows.map(c => `
    <tr>
      <td>${c.customer}</td>
      <td>${c.revenue}</td>
      <td>${c.orders}</td>
      <td>${c.average_order_value}</td>
    </tr>
  `).join('');
}

const html = `
<html>
<head>
  <title>Sales Report</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 40px; color: #222; }
    h1 { color: #1a1a1a; }
    h2 { color: #333; border-bottom: 1px solid #ddd; padding-bottom: 4px; }
    table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
    th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
    th { background-color: #f4f4f4; }
    .kpi-grid { display: flex; flex-wrap: wrap; gap: 16px; margin-bottom: 20px; }
    .kpi-box { border: 1px solid #ddd; border-radius: 6px; padding: 12px 16px; min-width: 160px; }
    .kpi-box .label { font-size: 12px; color: #666; }
    .kpi-box .value { font-size: 20px; font-weight: bold; }
    hr { border: none; border-top: 1px solid #ddd; margin: 24px 0; }
  </style>
</head>
<body>
  <h1>AI Sales Analyst</h1>

  <h2>KPIs</h2>
  <div class="kpi-grid">
    <div class="kpi-box"><div class="label">Gross Revenue</div><div class="value">${kpi.gross_revenue}</div></div>
    <div class="kpi-box"><div class="label">Net Revenue</div><div class="value">${kpi.net_revenue}</div></div>
    <div class="kpi-box"><div class="label">Gross Profit</div><div class="value">${kpi.gross_profit}</div></div>
    <div class="kpi-box"><div class="label">Gross Margin</div><div class="value">${kpi.gross_margin}%</div></div>
    <div class="kpi-box"><div class="label">Average Order Value</div><div class="value">${kpi.average_order_value}</div></div>
    <div class="kpi-box"><div class="label">Total Orders</div><div class="value">${kpi.total_orders}</div></div>
    <div class="kpi-box"><div class="label">Units Sold</div><div class="value">${kpi.units_sold}</div></div>
    <div class="kpi-box"><div class="label">Completed Orders</div><div class="value">${kpi.completed_orders}</div></div>
    <div class="kpi-box"><div class="label">Cancelled Orders</div><div class="value">${kpi.cancelled_orders}</div></div>
    <div class="kpi-box"><div class="label">Returned Orders</div><div class="value">${kpi.returned_orders}</div></div>
  </div>

  <hr>

  <h2>Top Products</h2>
  <table>
    <tr><th>Product</th><th>Category</th><th>Revenue</th><th>Profit</th><th>Units</th><th>Orders</th></tr>
    ${renderProductRows(topProducts)}
  </table>

  <hr>

  <h2>Top Categories</h2>
  <table>
    <tr><th>Category</th><th>Revenue</th><th>Profit</th><th>Units</th></tr>
    ${renderCategoryRows(categoryPerformance)}
  </table>

  <hr>

  <h2>Top Customers</h2>
  <table>
    <tr><th>Customer</th><th>Revenue</th><th>Orders</th><th>Average Order Value</th></tr>
    ${renderCustomerRows(topCustomers)}
  </table>

  <hr>

  <h2>AI Executive Summary</h2>
  <div>${ai.summary}</div>

  <hr>

  <h2>Recommendations</h2>
  <div>${ai.chat}</div>

</body>
</html>
`;

return [
  {
    json: {
      html
    }
  }
];
